"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["63511"],{9809(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.falta_em_dia_de_prova_enem_repetida","status":422,"titulo":"A elimina\xe7\xe3o por falta em dia de prova do ENEM s\xf3 pode ser declarada uma vez"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.falta_em_dia_de_prova_enem_repetida","requisitos":[],"oQueAconteceu":["A lista `regrasEliminacao` da classifica\xe7\xe3o traz a elimina\xe7\xe3o por falta em dia de prova do\\nENEM (`ELIMINACAO_FALTA_EM_DIA_DE_PROVA_ENEM`) mais de uma vez. Essa regra n\xe3o tem par\xe2metros; uma\\nsegunda declara\xe7\xe3o repete a primeira e n\xe3o elimina ningu\xe9m a mais. A primeira vale; cada\\nrepeti\xe7\xe3o \xe9 recusada no pr\xf3prio item, no campo `regrasEliminacao[i]`, e acumula no array\\n`errors[]` com as demais viola\xe7\xf5es da requisi\xe7\xe3o.","Esta causa \xe9 independente de\\n[`eliminacao_enem_fora_de_processo_enem`](/erros/uniplus.selecao.processo_seletivo.eliminacao_enem_fora_de_processo_enem):\\na classifica\xe7\xe3o com a elimina\xe7\xe3o repetida e sem a marca\xe7\xe3o de baseada em ENEM reprova as duas\\njuntas.","A confer\xeancia s\xf3 vale para classifica\xe7\xe3o com c\xe1lculo local. Na classifica\xe7\xe3o importada, que\\nn\xe3o admite regra de elimina\xe7\xe3o nenhuma, a recusa \xe9 a da lista inteira, em\\n[`eliminacao_indevida`](/erros/uniplus.selecao.configuracao_classificacao.eliminacao_indevida).","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na defini\xe7\xe3o da classifica\xe7\xe3o, mantenha uma s\xf3 elimina\xe7\xe3o por falta em dia de prova do ENEM e\\nremova as repeti\xe7\xf5es.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);